import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Create container group for divider element
  const group = new THREE.Group();

  // Apply scene placement
  const position = config.position || [-2.5, 0.7, 0];
  const rotation = config.rotation || [0, 0, 0];
  const scale = config.scale || [1, 1, 1];

  group.position.set(...position);
  group.rotation.set(...rotation);
  group.scale.set(...scale);

  // Load GLB mesh
  const gltf = ctx.glbLoader.load(config.meshUrl);
  const modelScene = gltf.scene.clone();
  group.add(modelScene);

  // Interaction state
  let isHovered = false;
  const activeTimelines = [];
  const baseY = position[1];

  // Initialize event handlers
  group.userData.handlers = {};

  // Hover enter: rise-in (lift by 0.15 units, power3.out, 0.7s)
  group.userData.handlers.onPointerEnter = () => {
    if (isHovered) return;
    isHovered = true;

    activeTimelines.forEach(tl => tl.kill());
    activeTimelines.length = 0;

    const tl = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    activeTimelines.push(tl);
  };

  // Hover exit: return to base position
  group.userData.handlers.onPointerLeave = () => {
    if (!isHovered) return;
    isHovered = false;

    activeTimelines.forEach(tl => tl.kill());
    activeTimelines.length = 0;

    const tl = gsap.to(group.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out'
    });
    activeTimelines.push(tl);
  };

  // Click: emit hub-home.select event
  group.userData.handlers.onClick = () => {
    if (ctx.emit) {
      ctx.emit('hub-home.select', {});
    }
  };

  // Slot data binding handler
  group.userData.handlers.onSlotUpdate = (slotData) => {
    group.userData.currentSlot = slotData;
  };

  // Cleanup: dispose resources and kill animations
  group.userData.cleanup = () => {
    activeTimelines.forEach(tl => tl.kill());
    activeTimelines.length = 0;

    modelScene.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(m => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
